#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <transport/transport_layer.h>
// pydoc.h is automatically generated in the build directory
#include <transport_layer_pydoc.h>

void bind_transport_layer(py::module& m)
{

    using transport_layer    = gr::transport::transport_layer;


    py::class_<transport_layer, gr::block, gr::basic_block,
        std::shared_ptr<transport_layer>>(m, "transport_layer", D(transport_layer))

        .def(py::init(&transport_layer::make),
           py::arg("m") =  4,
           py::arg("rto_ms") =  500,
           py::arg("node_role") =  "initiator",
           py::arg("mtu_bytes") =  200,
           D(transport_layer,make)
        )
        



        ;




}








